// schemaCol is one PRAGMA table_info row's shape: the declared type, the
// NOT NULL flag, the literal DEFAULT text (SQLite echoes the declaration
// verbatim, quotes included) and the 1-based position within the PRIMARY KEY
// (0 for a non-PK column).
type schemaCol struct {
	ctype   string
	notnull bool
	dflt    sql.NullString
	pk      int
}

