// tableColumns reads PRAGMA table_info(table) into a name→schemaCol map.
func tableColumns(t *testing.T, ctx context.Context, db *sql.DB, table string) map[string]schemaCol {
	t.Helper()
	rows, err := db.QueryContext(ctx, "PRAGMA table_info("+table+")")
	if err != nil {
		t.Fatalf("PRAGMA table_info(%s): %v", table, err)
	}
	defer rows.Close()
	cols := map[string]schemaCol{}
	for rows.Next() {
		var (
			cid  int
			name string
			col  schemaCol
			notn int
			dflt sql.NullString
		)
		if err := rows.Scan(&cid, &name, &col.ctype, &notn, &dflt, &col.pk); err != nil {
			t.Fatalf("PRAGMA table_info(%s) scan: %v", table, err)
		}
		col.notnull = notn == 1
		col.dflt = dflt
		cols[name] = col
	}
	if err := rows.Err(); err != nil {
		t.Fatalf("PRAGMA table_info(%s) rows: %v", table, err)
	}
	return cols
}

// tableDDL reads the stored CREATE statement for a table out of sqlite_master.
func tableDDL(t *testing.T, ctx context.Context, db *sql.DB, table string) string {
	t.Helper()
	var ddl string
	if err := db.QueryRowContext(ctx,
		`SELECT sql FROM sqlite_master WHERE type = 'table' AND name = ?`, table).Scan(&ddl); err != nil {
		t.Fatalf("sqlite_master DDL for %s: %v", table, err)
	}
	return ddl
}

// TestAccountsSchemaFresh pins the five accounts tables' fresh-DB shape (task
// 2.1): columns via PRAGMA table_info (names, types, NOT NULL, DEFAULT text,
// PK positions), the CHECK constraints behaviorally (a violating insert must
// fail; its valid twin must succeed), the UNIQUE constraints behaviorally
// (a duplicate insert must fail), and the credentials→users foreign key plus
// the AUTOINCREMENT ids structurally (visible only in the stored DDL —
// PRAGMA table_info exposes neither).
func TestAccountsSchemaFresh(t *testing.T) {
	ctx := context.Background()
	s := openStore(t)

	for table, wantCols := range accountsSchema {
		gotCols := tableColumns(t, ctx, s.db, table)
		if len(gotCols) != len(wantCols) {
			t.Fatalf("%s: %d columns, want %d (got %v)", table, len(gotCols), len(wantCols), gotCols)
		}
		for name, want := range wantCols {
			got, ok := gotCols[name]
			if !ok {
				t.Fatalf("%s: column %q missing", table, name)
			}
			if got.ctype != want.ctype {
				t.Errorf("%s.%s type = %q, want %q", table, name, got.ctype, want.ctype)
			}
			if got.notnull != want.notnull {
				t.Errorf("%s.%s notnull = %v, want %v", table, name, got.notnull, want.notnull)
			}
			if got.dflt != want.dflt {
				t.Errorf("%s.%s default = %v, want %v", table, name, got.dflt, want.dflt)
			}
			if got.pk != want.pk {
				t.Errorf("%s.%s pk position = %d, want %d", table, name, got.pk, want.pk)
			}
		}
	}

	// AUTOINCREMENT ids on the deletable entity tables (users/groups): rowid
	// reuse after a delete must never alias a dead id.
	for _, table := range []string{"users", "groups"} {
		if ddl := tableDDL(t, ctx, s.db, table); !strings.Contains(ddl, "AUTOINCREMENT") {
			t.Errorf("%s: DDL lacks AUTOINCREMENT: %s", table, ddl)
		}
	}

	// The credentials.user_id foreign key is structural, not behavioral:
	// SQLite leaves FK enforcement OFF per connection, so the REFERENCES
	// clause is only provable in the stored DDL.
	if ddl := tableDDL(t, ctx, s.db, "credentials"); !strings.Contains(ddl, "REFERENCES users(id)") {
		t.Errorf("credentials: DDL lacks REFERENCES users(id): %s", ddl)
	}

	// Baseline valid rows (the CHECK/UNIQUE probes below deviate from these
	// one column at a time, so a failure is that constraint, not noise).
	res, err := s.db.ExecContext(ctx, `INSERT INTO users
		(username, display_name, password_hash, role, prefs_json, disabled, created_at, updated_at)
		VALUES ('anna', 'Anna', 'argon2id$hash', 'user', '{}', 0, '2026-11-04T00:00:00Z', '2026-11-04T00:00:00Z')`)
	if err != nil {
		t.Fatalf("valid users insert failed: %v", err)
	}
	userID, err := res.LastInsertId()
	if err != nil {
		t.Fatalf("users LastInsertId: %v", err)
	}
	if _, err := s.db.ExecContext(ctx, `INSERT INTO credentials
		(kind, token_hash, user_id, label, created_at, expires_at)
		VALUES ('device', 'deadbeef', ?, 'living room tv', '2026-11-04T00:00:00Z', NULL)`, userID); err != nil {
		t.Fatalf("valid credentials insert failed: %v", err)
	}
	if _, err := s.db.ExecContext(ctx, `INSERT INTO groups
		(name, doc_json, schema_version, created_at, updated_at)
		VALUES ('kids', '{}', 1, '2026-11-04T00:00:00Z', '2026-11-04T00:00:00Z')`); err != nil {
		t.Fatalf("valid groups insert failed: %v", err)
	}
	if _, err := s.db.ExecContext(ctx,
		`INSERT INTO group_collections (group_id, library_id, position) VALUES (1, 7, 3)`); err != nil {
		t.Fatalf("valid group_collections insert failed: %v", err)
	}
	if _, err := s.db.ExecContext(ctx,
		`INSERT INTO group_members (group_id, user_id) VALUES (1, ?)`, userID); err != nil {
		t.Fatalf("valid group_members insert failed: %v", err)
	}

	// CHECK constraints: out-of-vocabulary role and kind must refuse.
	if _, err := s.db.ExecContext(ctx, `INSERT INTO users
		(username, display_name, password_hash, role, prefs_json, disabled, created_at, updated_at)
		VALUES ('bad', '', 'h', 'superuser', '{}', 0, 't', 't')`); err == nil {
		t.Error("users.role CHECK not enforced: 'superuser' row accepted")
	}
	if _, err := s.db.ExecContext(ctx, `INSERT INTO credentials
		(kind, token_hash, user_id, label, created_at, expires_at)
		VALUES ('apikey', 'cafebabe', NULL, '', 't', NULL)`); err == nil {
		t.Error("credentials.kind CHECK not enforced: 'apikey' row accepted")
	}

	// UNIQUE constraints: duplicates on each declared-unique axis must refuse.
	if _, err := s.db.ExecContext(ctx, `INSERT INTO users
		(username, display_name, password_hash, role, prefs_json, disabled, created_at, updated_at)
		VALUES ('anna', 'Dup', 'h2', 'admin', '{}', 0, 't', 't')`); err == nil {
		t.Error("users.username UNIQUE not enforced: duplicate accepted")
	}
	if _, err := s.db.ExecContext(ctx, `INSERT INTO groups
		(name, doc_json, schema_version, created_at, updated_at)
		VALUES ('kids', '{}', 1, 't', 't')`); err == nil {
		t.Error("groups.name UNIQUE not enforced: duplicate accepted")
	}
	if _, err := s.db.ExecContext(ctx, `INSERT INTO credentials
		(kind, token_hash, user_id, label, created_at, expires_at)
		VALUES ('session', 'deadbeef', NULL, '', 't', NULL)`); err == nil {
		t.Error("credentials.token_hash UNIQUE not enforced: duplicate accepted")
	}
	if _, err := s.db.ExecContext(ctx,
		`INSERT INTO group_collections (group_id, library_id, position) VALUES (1, 7, 9)`); err == nil {
		t.Error("group_collections (group_id, library_id) UNIQUE pair not enforced: duplicate accepted")
	}
	if _, err := s.db.ExecContext(ctx,
		`INSERT INTO group_members (group_id, user_id) VALUES (1, ?)`, userID); err == nil {
		t.Error("group_members (group_id, user_id) UNIQUE pair not enforced: duplicate accepted")
	}
}
